urlset:
{% spaceless %}
{% for url in urlset %}

  {{ url.location }}
  {% if url.lastmod %}{{ url.lastmod|date:"Y-m-d" }}{% endif %}
  {% if url.changefreq %}{{ url.changefreq }}{% endif %}
  {% if url.priority %}{{ url.priority }}{% endif %}
  {% if url.item.cover_image %}

    {{ request.scheme }}://{{ request.get_host }}{{ url.item.cover_image.url }}
    {{ url.item.name|default:"" }}

  {% elif url.item.featured_image %}

    {{ request.scheme }}://{{ request.get_host }}{{ url.item.featured_image.url }}
    {{ url.item.title|default:"" }}

  {% elif url.item == "home:home" %}

    {{ request.scheme }}://{{ request.get_host }}/static/home/images/og-brand.jpg
    سیدوس | صنایع دکوراتیو و ظروف خانه

  {% endif %}

{% endfor %}
{% endspaceless %}
